<script lang="ts">
 import {zh} from './zh';
 import {engine} from '../../bridge/engine.svelte';import AriaSymbol from './AriaSymbol.svelte';
 let {onclose,onerror}:{onclose:()=>void;onerror:(message:string)=>void}=$props();
 let data=$state(engine.scorePanels()),width=$state(700),dragged=$state(''),over=$state(''),dragTimer:ReturnType<typeof setTimeout>,surface:HTMLDivElement;
 const compact=$derived(width<520);
 function move(id:string,target:string){if(!id||id===target)return;const from=data.parts.findIndex(p=>p.id===id),to=data.parts.findIndex(p=>p.id===target);const result=engine.changeParts({op:'move-part',id,target,after:from<to});if(!result.ok)onerror('Instrument order could not be changed.');data=engine.scorePanels();}
 function down(e:PointerEvent,id:string){const target=e.currentTarget as HTMLElement;dragTimer=setTimeout(()=>{dragged=id;over=id;target.setPointerCapture(e.pointerId);},400);}
 function pointerMove(e:PointerEvent){if(!dragged)return;const rows=[...surface.querySelectorAll<HTMLElement>('[data-part]')];const target=rows.find(row=>{const rect=row.getBoundingClientRect();return e.clientY>=rect.top&&e.clientY<=rect.bottom;});if(target)over=target.dataset.part||'';}
 function up(){clearTimeout(dragTimer);if(dragged&&over)move(dragged,over);dragged='';over='';}
</script>
<div class="part-layout" class:compact bind:clientWidth={width} bind:this={surface}>
 <div class="aria-form-header"><span></span><strong>乐器排列</strong><button onclick={onclose}>完成</button></div>
 <div class="part-card"><div class="part-header"><span></span><strong>乐器</strong><small>显示</small></div>{#each data.parts as part}<div class="part-row" class:dragging={dragged===part.id} class:drop-target={!!dragged&&over===part.id} data-part={part.id}><button class="drag-handle" aria-label={zh('Reorder '+part.name)} onpointerdown={e=>down(e,part.id)} onpointermove={pointerMove} onpointerup={up} onpointercancel={up}><AriaSymbol name="line.3.horizontal" size={compact?13:14}/></button><strong>{part.name}</strong><label><span class="sr-only">Show {part.name}</span><input type="checkbox" checked={part.visible} onchange={e=>{const reply=engine.changeParts({op:'part-visible',id:part.id,visible:e.currentTarget.checked});if(!reply.ok)onerror('Visibility could not be changed.');data=engine.scorePanels();}}/></label></div>{/each}</div>
</div>
<style>.part-layout{min-height:340px;background:#f3f2f7;}.part-card{width:min(calc(100% - 56px),680px);margin:22px auto 24px;background:white;border-radius:22px;outline:1px solid #0000000f;overflow:hidden;}.part-header,.part-row{display:flex;align-items:center;gap:12px;padding:0 20px;}.part-header{padding-block:14px;font-size:13px;font-weight:600;color:#0008;border-bottom:.5px solid #0002;}.part-header>span{width:30px;flex:none;}.part-header>strong,.part-row>strong{flex:1;min-width:0;}.part-header>small,.part-row>label{width:132px;text-align:center;flex:none;}.part-row{min-height:74px;}.part-row+.part-row{border-top:.5px solid #0002;}.part-row>strong{font-size:20px;}.drag-handle{width:30px;height:44px;min-height:0;flex:none;display:grid;place-items:center;background:none;border:0;border-radius:0;color:#0007;touch-action:none;}.part-row input{width:42px;height:24px;accent-color:#007aff;}.compact .part-card{width:calc(100% - 28px);margin-top:14px;border-radius:18px;}.compact .part-header,.compact .part-row{gap:10px;padding-inline:14px;}.compact .part-header{padding-block:12px;font-size:12px;}.compact .part-header>span,.compact .drag-handle{width:24px;}.compact .part-header>small,.compact .part-row>label{width:96px;}.compact .part-row{min-height:66px;}.compact .part-row>strong{font-size:17px;}.dragging{opacity:.5;}.drop-target{background:#007aff15;}.sr-only{position:absolute;width:1px;height:1px;clip-path:inset(50%);overflow:hidden;white-space:nowrap;}</style>
